import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷五·4","description":"易小帖 - 卷五·4","frontmatter":{"title":"卷五·4","description":"易小帖 - 卷五·4"},"headers":[],"relativePath":"zh/classics/yixiaotie/126.md","filePath":"zh/classics/yixiaotie/126.md"}'),o={name:"zh/classics/yixiaotie/126.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷五·4",tabindex:"-1"},[r("卷五·4 "),e("a",{class:"header-anchor",href:"#卷五·4","aria-label":"Permalink to “卷五·4”"},"​")],-1),e("p",null,"此其中有至理焉，極者至也。所謂易其至焉者也，其在天地以不二之物而生陰生陽生四時，以生萬物，此天地之至理也。乃易亦有之。以羲卦言，太極一畫也，一畫者理之至也，即陽也，乾也，乃以一生兩，則生坤也。坤象乾，故曰儀，儀者則也。生坤而陰陽具矣，乃取乾坤各二之，以成四象，如二乾為巽離兌，二坤為震坎艮，則兩陰兩陽，合之為四，而於是八卦成焉。（三索以一言，四象以二言。《珠囊集》曰：陽二畫，陰二畫，即四象也。）乃以之推易，則乾坤成列，為太極陰陽對聚為兩儀。易止於四，為四象。（移易以一卦始，以四卦止。）而以之揲蓍，則象兩。象四前文可驗也。故自八卦成而剛柔相推，以之屬辭，即以之揲筮通民志而定大業，皆在於此。（繫辭以明吉凶，就繫辭言，此就占卦言。然繫辭所以占卦，故兩屬之。）",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
